import json
import sys

targetTypeRaw = sys.argv[1]
organizationRaw = sys.argv[2]
targetNameRaw = sys.argv[3]
firmwareVersionRaw = sys.argv[4]
imageSourceRaw = sys.argv[5]
serverModeRaw = sys.argv[6]
skipEstimateRaw = sys.argv[7]
excludedComponentsRaw = sys.argv[8]
excludedPidsRaw = sys.argv[9]
xfmRaw = sys.argv[10]
fabricEvacuationRaw = sys.argv[11]
switchWaitRaw = sys.argv[12]
psuRaw = sys.argv[13]
pdbRaw = sys.argv[14]
skipIoRaw = sys.argv[15]
waitRaw = sys.argv[16]
waitTimeoutRaw = sys.argv[17]

targetType = targetTypeRaw.strip()
organizationName = organizationRaw.strip()
targetName = targetNameRaw.strip()
firmwareVersion = firmwareVersionRaw.strip()
imageSource = imageSourceRaw.strip()
serverUpgradeMode = serverModeRaw.strip()
xfmUpgradeOption = xfmRaw.strip()
excludedComponentsText = excludedComponentsRaw.strip()
excludedPidsText = excludedPidsRaw.strip()
errors = []

for raw, clean, label in ((targetTypeRaw, targetType, "Target Type"), (organizationRaw, organizationName, "Device Organization"), (targetNameRaw, targetName, "Target Name"), (firmwareVersionRaw, firmwareVersion, "Firmware Version"), (imageSourceRaw, imageSource, "Image Source"), (serverModeRaw, serverUpgradeMode, "Server Upgrade Mode"), (xfmRaw, xfmUpgradeOption, "XFM Upgrade Option"), (excludedComponentsRaw, excludedComponentsText, "Excluded Components"), (excludedPidsRaw, excludedPidsText, "Excluded Component PIDs")):
    if raw != clean:
        errors.append(label + " must not contain surrounding whitespace.")

def strict_bool(value, label):
    if value not in ("True", "False"):
        errors.append(label + " must be a boolean.")
        return False
    return value == "True"

def strict_int(value, label):
    try:
        parsed = int(value)
    except Exception:
        errors.append(label + " must be an integer.")
        return 0
    if str(parsed) != value and not (value == "-0" and parsed == 0):
        errors.append(label + " must use canonical integer syntax.")
    return parsed

skipEstimateImpact = strict_bool(skipEstimateRaw, "Skip Estimate Impact")
enableFabricEvacuation = strict_bool(fabricEvacuationRaw, "Enable Fabric Evacuation")
enablePsuUpgrade = strict_bool(psuRaw, "Enable PSU Upgrade")
enablePdbFpgaUpgrade = strict_bool(pdbRaw, "Enable PDB FPGA Upgrade")
skipWaitForIo = strict_bool(skipIoRaw, "Skip Wait for I/O Connectivity")
waitForCompletion = strict_bool(waitRaw, "Wait for Completion")
switchWaitTimeout = strict_int(switchWaitRaw, "Switch Wait Timeout Minutes")
waitTimeoutSeconds = strict_int(waitTimeoutRaw, "Wait Timeout Seconds")

allowedTargets = {"Domain", "UCS-X Chassis", "Unified Edge Chassis (eCMC)", "Server"}
if targetType not in allowedTargets:
    errors.append("Target Type must exactly match Domain, UCS-X Chassis, Unified Edge Chassis (eCMC), or Server.")
if imageSource != "Cisco Repository":
    errors.append("Image Source must be exactly Cisco Repository; v1 does not accept local repository or network-share credentials.")

def validate_odata(value, label, maximum):
    if not value or len(value) > maximum or any(ord(ch) < 32 or ch in "&?#%" for ch in value):
        errors.append(label + " must contain 1-" + str(maximum) + " characters and must not contain control or URL query-delimiter characters.")

validate_odata(organizationName, "Device Organization", 64)
validate_odata(targetName, "Target Name", 128)
validate_odata(firmwareVersion, "Firmware Version", 128)

excludedComponents = []
if excludedComponentsText:
    try:
        excludedComponents = json.loads(excludedComponentsText)
    except Exception:
        errors.append("Excluded Components must be valid JSON.")
        excludedComponents = []
    if not isinstance(excludedComponents, list) or any(not isinstance(v, str) or not v for v in excludedComponents):
        errors.append("Excluded Components must be a JSON array of non-empty strings.")
        excludedComponents = []
    elif len(excludedComponents) != len(set(excludedComponents)):
        errors.append("Excluded Components must not contain duplicates.")

excludedPidObject = None
if excludedPidsText:
    try:
        excludedPidObject = json.loads(excludedPidsText)
    except Exception:
        errors.append("Excluded Component PIDs must be valid JSON.")
    if excludedPidObject is not None:
        allowedKeys = {"ExcludeLocalDiskList", "ExcludeStorageControllerList"}
        if not isinstance(excludedPidObject, dict) or not excludedPidObject or set(excludedPidObject) - allowedKeys:
            errors.append("Excluded Component PIDs must be a non-empty object containing only ExcludeLocalDiskList and/or ExcludeStorageControllerList.")
            excludedPidObject = None
        else:
            for key, values in excludedPidObject.items():
                if not isinstance(values, list) or not values or any(not isinstance(v, str) or not v.strip() or v != v.strip() or len(v) > 128 for v in values) or len(values) != len(set(values)):
                    errors.append(key + " must be a non-empty array of unique, exact, non-empty strings no longer than 128 characters.")
                    excludedPidObject = None
                    break

serverAllowed = {"none", "local-disk", "drives-except-boot-drives", "storage-controller", "storage-sasexpander", "storage-u2"}
chassisAllowed = {"none", "local-disk", "psu", "xfm"}
if "none" in excludedComponents and len(excludedComponents) != 1:
    errors.append("Excluded Components value none is mutually exclusive with every other component.")

switchOptionsChanged = (enableFabricEvacuation is not True or switchWaitTimeout != 0 or enablePsuUpgrade or enablePdbFpgaUpgrade or skipWaitForIo)
if targetType == "Server":
    if serverUpgradeMode not in ("Start Immediately", "Mount Only"):
        errors.append("Server Upgrade Mode must be Start Immediately or Mount Only for Server.")
    if any(v not in serverAllowed for v in excludedComponents):
        errors.append("Excluded Components contains a value not supported by firmware.Upgrade.")
    if xfmUpgradeOption != "none":
        errors.append("XFM Upgrade Option applies only to UCS-X Chassis and must remain none for Server.")
    if switchOptionsChanged:
        errors.append("Switch-only evacuation, wait-timeout, PSU, PDB FPGA, and I/O-connectivity options must retain defaults for Server.")
elif targetType == "UCS-X Chassis":
    if serverUpgradeMode != "Start Immediately" or skipEstimateImpact:
        errors.append("Server Upgrade Mode and Skip Estimate Impact are server-only and must retain defaults for UCS-X Chassis.")
    if any(v not in chassisAllowed for v in excludedComponents):
        errors.append("Excluded Components contains a value not supported by firmware.ChassisUpgrade.")
    if excludedPidObject is not None:
        errors.append("Excluded Component PIDs is not supported by firmware.ChassisUpgrade.")
    if xfmUpgradeOption not in ("none", "full-shutdown", "partial-shutdown"):
        errors.append("XFM Upgrade Option must be none, full-shutdown, or partial-shutdown.")
    if switchOptionsChanged:
        errors.append("Switch-only evacuation, wait-timeout, PSU, PDB FPGA, and I/O-connectivity options must retain defaults for UCS-X Chassis.")
elif targetType in ("Domain", "Unified Edge Chassis (eCMC)"):
    if serverUpgradeMode != "Start Immediately" or skipEstimateImpact or excludedComponents or excludedPidObject is not None or xfmUpgradeOption != "none":
        errors.append("Server/chassis-only mode, estimate, exclusion, PID, and XFM options must retain defaults for Domain/eCMC.")
    if switchWaitTimeout < -1 or switchWaitTimeout > 1000:
        errors.append("Switch Wait Timeout Minutes must be from -1 through 1000.")

if waitForCompletion:
    if waitTimeoutSeconds < 1 or waitTimeoutSeconds > 600:
        errors.append("Wait Timeout Seconds must be from 1 through 600 when Wait for Completion is true.")
elif waitTimeoutSeconds != 0:
    errors.append("Wait Timeout Seconds must remain numeric 0 when Wait for Completion is false.")

escapedOrganizationName = organizationName.replace("'", "''")
escapedTargetName = targetName.replace("'", "''")
escapedFirmwareVersion = firmwareVersion.replace("'", "''")
targetApiUrl = ""
expectedTargetObjectType = ""
if targetType == "Server":
    expectedTargetObjectType = "compute.PhysicalSummary"
    targetApiUrl = "/api/v1/compute/PhysicalSummaries?$filter=Name eq '" + escapedTargetName + "' and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,Model,ManagementMode,SourceObjectType,ObjectType,ClassId,PermissionResources"
elif targetType == "UCS-X Chassis":
    expectedTargetObjectType = "equipment.Chassis"
    targetApiUrl = "/api/v1/equipment/Chasses?$filter=Name eq '" + escapedTargetName + "' and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,Model,PlatformType,ObjectType,ClassId,PermissionResources"
elif targetType == "Unified Edge Chassis (eCMC)":
    expectedTargetObjectType = "network.Element"
    targetApiUrl = "/api/v1/network/Elements?$filter=Name eq '" + escapedTargetName + "' and SwitchType eq 'EdgeChassisManagementController' and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,Model,PlatformType,SwitchId,SwitchType,ObjectType,ClassId,PermissionResources"
elif targetType == "Domain":
    expectedTargetObjectType = "top.System"
    targetApiUrl = "/api/v1/top/Systems?$filter=Name eq '" + escapedTargetName + "' and PermissionResources/any(t:t/Moid eq '{organizationMoid}')&$select=Moid,Name,ObjectType,ClassId,PermissionResources&$expand=NetworkElements($select=Moid,Name,Model,SwitchId,SwitchType,ObjectType,ClassId)"

preparationStatus = "invalid" if errors else "ready"
preparationMessage = " ".join(errors) if errors else "Inputs, cross-field routing, JSON shapes, enum values, and all OData string escaping were validated."
preparationResultJson = json.dumps({
    "validated": not errors,
    "errors": errors,
    "targetType": targetType,
    "deviceOrganization": organizationName,
    "targetName": targetName,
    "firmwareVersion": firmwareVersion,
    "imageSource": imageSource,
    "serverUpgradeMode": serverUpgradeMode,
    "skipEstimateImpact": skipEstimateImpact,
    "excludedComponents": excludedComponents,
    "excludedComponentPids": excludedPidObject,
    "xfmUpgradeOption": xfmUpgradeOption,
    "enableFabricEvacuation": enableFabricEvacuation,
    "switchWaitTimeoutMinutes": switchWaitTimeout,
    "enablePsuUpgrade": enablePsuUpgrade,
    "enablePdbFpgaUpgrade": enablePdbFpgaUpgrade,
    "skipWaitForIoPathConnectivity": skipWaitForIo,
    "waitForCompletion": waitForCompletion,
    "waitTimeoutSeconds": waitTimeoutSeconds,
    "acceptedVersusCompletedSemantics": True,
    "ciscoRepositoryOnly": True
}, separators=(",", ":"))
helperReady = preparationStatus in ("invalid", "ready") and bool(preparationMessage and preparationResultJson) and (preparationStatus != "ready" or bool(targetApiUrl and expectedTargetObjectType))

import json
import re
import sys
payload = json.loads(sys.argv[1])
target = json.loads(sys.argv[2])
prepared = json.loads(sys.argv[3])
values = payload.get("Results")
if not isinstance(values, list):
    raise ValueError("Active firmware response is missing a Results array")

def safe_moid(value):
    return isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", value) is not None

def relation_matches(rel, moid, objectType):
    return isinstance(rel, dict) and rel.get("Moid") == moid and rel.get("ObjectType") == objectType and rel.get("ClassId") in (None, "mo.MoRef", objectType)

targetType = prepared.get("targetType")
expectedType = {"Server": "firmware.Upgrade", "UCS-X Chassis": "firmware.ChassisUpgrade", "Domain": "firmware.SwitchUpgrade"}.get(targetType)
problems = []
active = []
for index, item in enumerate(values):
    if not isinstance(item, dict):
        problems.append("Existing firmware result " + str(index) + " is not an object.")
        continue
    if not safe_moid(item.get("Moid")) or item.get("ObjectType") != expectedType or item.get("ClassId") != expectedType:
        problems.append("Existing firmware result " + str(index) + " has invalid identity or discriminators.")
        continue
    status = item.get("Status")
    if status not in ("NONE", "IN_PROGRESS", "SUCCESSFUL", "FAILED", "TERMINATED"):
        problems.append("Existing firmware result " + str(index) + " has an undocumented Status.")
        continue
    if targetType == "Server":
        if not relation_matches(item.get("Server"), target.get("targetMoid"), target.get("sourceObjectType")):
            problems.append("Existing server firmware result does not match the validated concrete server relationship.")
            continue
    elif targetType == "UCS-X Chassis":
        if not relation_matches(item.get("Chassis"), target.get("targetMoid"), "equipment.Chassis"):
            problems.append("Existing chassis firmware result does not match the validated chassis relationship.")
            continue
    elif targetType == "Domain":
        expectedMoids = {entry.get("Moid") for entry in target.get("networkElements", []) if isinstance(entry, dict)}
        returned = item.get("NetworkElements")
        returnedMoids = {entry.get("Moid") for entry in returned if isinstance(entry, dict) and relation_matches(entry, entry.get("Moid"), "network.Element")} if isinstance(returned, list) else set()
        if not isinstance(returned, list) or len(returned) != 2 or returnedMoids != expectedMoids:
            problems.append("Existing switch firmware result does not exactly match the two validated domain FI relationships.")
            continue
    if status in ("NONE", "IN_PROGRESS"):
        active.append({"Moid": item["Moid"], "Status": status, "ObjectType": expectedType})

if problems:
    preflightStatus = "invalid"
    preflightMessage = " ".join(problems)
elif active:
    preflightStatus = "conflict"
    preflightMessage = "The exact target already has " + str(len(active)) + " active NONE/IN_PROGRESS firmware resource(s); no duplicate create was submitted."
else:
    preflightStatus = "clear"
    preflightMessage = "No exact active firmware resource blocks this create. The read-before-create duplicate race remains and is documented."
preflightResultJson = json.dumps({
    "status": preflightStatus,
    "message": preflightMessage,
    "targetType": targetType,
    "targetMoid": target.get("targetMoid"),
    "activeResources": active,
    "bestEffortIdempotencyGuard": True,
    "duplicateRaceRemains": True,
    "requestAccepted": False
}, separators=(",", ":"))
helperReady = preflightStatus in ("invalid", "conflict", "clear") and bool(preflightMessage and preflightResultJson)

import json
import re
import sys
payload = json.loads(sys.argv[1])
statusCode = int(sys.argv[2])
target = json.loads(sys.argv[3])
image = json.loads(sys.argv[4])
prepared = json.loads(sys.argv[5])
submitObjectType = sys.argv[6]
imageMoid = sys.argv[7]
imageObjectType = sys.argv[8]
createdCollection = sys.argv[9]
preflight = json.loads(sys.argv[10])

def safe_moid(value):
    return isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}", value) is not None

def relation_matches(rel, moid, objectType):
    return isinstance(rel, dict) and rel.get("Moid") == moid and rel.get("ObjectType") == objectType and rel.get("ClassId") in (None, "mo.MoRef", objectType)

problems = []
createdMoid = ""
upgradeStatusMoid = ""
pollMode = ""
pollApiUrl = ""
if statusCode != 200:
    problems.append("Firmware create response status is not documented HTTP 200.")
if not isinstance(payload, dict):
    problems.append("Firmware create response is not an object.")
else:
    createdMoid = str(payload.get("Moid") or "")
    if not safe_moid(createdMoid):
        problems.append("Created firmware resource Moid is missing or not URL-safe.")
    if payload.get("ObjectType") != submitObjectType or payload.get("ClassId") != submitObjectType:
        problems.append("Created firmware resource discriminators do not match the submitted concrete type.")
    targetType = prepared.get("targetType")
    if targetType == "Server":
        if not relation_matches(payload.get("Server"), target.get("targetMoid"), target.get("sourceObjectType")):
            problems.append("Returned Server relationship does not match the validated concrete Blade/RackUnit target.")
        if not relation_matches(payload.get("Distributable"), imageMoid, "firmware.Distributable"):
            problems.append("Returned Distributable relationship does not match the validated server image.")
        if payload.get("Release") not in (None, {}):
            problems.append("Server response unexpectedly contains Release.")
    elif targetType == "UCS-X Chassis":
        if not relation_matches(payload.get("Chassis"), target.get("targetMoid"), "equipment.Chassis"):
            problems.append("Returned Chassis relationship does not match the validated UCS-X target.")
        if not relation_matches(payload.get("Distributable"), imageMoid, "firmware.Distributable"):
            problems.append("Returned Distributable relationship does not match the validated chassis image.")
        if payload.get("Release") not in (None, {}):
            problems.append("Chassis response unexpectedly contains Release.")
    elif targetType == "Domain":
        returnedElements = payload.get("NetworkElements")
        expectedElements = {entry.get("Moid") for entry in target.get("networkElements", []) if isinstance(entry, dict)}
        returnedMoids = {entry.get("Moid") for entry in returnedElements if isinstance(entry, dict) and relation_matches(entry, entry.get("Moid"), "network.Element")} if isinstance(returnedElements, list) else set()
        if not isinstance(returnedElements, list) or len(returnedElements) != 2 or returnedMoids != expectedElements:
            problems.append("Returned NetworkElements do not exactly match the two validated domain FI A/B elements.")
        if not relation_matches(payload.get("Release"), imageMoid, "softwarerepository.Release"):
            problems.append("Returned Release relationship does not match the validated FabricSwitch Release.")
        if payload.get("Distributable") not in (None, {}):
            problems.append("Domain response unexpectedly populated Distributable; Release must never be placed there.")

    status = payload.get("Status")
    if status not in ("NONE", "IN_PROGRESS", "SUCCESSFUL", "FAILED", "TERMINATED"):
        problems.append("Created firmware resource Status is not a documented uppercase enum.")
    upgradeStatus = payload.get("UpgradeStatus")
    if upgradeStatus not in (None, {}):
        if not isinstance(upgradeStatus, dict) or not safe_moid(upgradeStatus.get("Moid")) or upgradeStatus.get("ObjectType") != "firmware.UpgradeStatus" or upgradeStatus.get("ClassId") not in (None, "mo.MoRef", "firmware.UpgradeStatus"):
            problems.append("UpgradeStatus relationship is malformed.")
        else:
            upgradeStatusMoid = upgradeStatus["Moid"]

if problems:
    submissionStatus = "invalid"
    submissionMessage = " ".join(problems)
elif payload.get("Status") in ("FAILED", "TERMINATED"):
    submissionStatus = "failed"
    submissionMessage = "The firmware resource was created but immediately returned terminal Status " + payload.get("Status") + "."
elif payload.get("Status") == "SUCCESSFUL":
    submissionStatus = "completed"
    submissionMessage = "The firmware resource was created and already reports Status SUCCESSFUL."
else:
    submissionStatus = "accepted"
    submissionMessage = "The firmware upgrade resource was accepted with documented HTTP 200; completion is not yet confirmed."

if submissionStatus in ("accepted", "completed", "failed"):
    if upgradeStatusMoid:
        pollMode = "upgrade-status"
        pollApiUrl = "/api/v1/firmware/UpgradeStatuses/" + upgradeStatusMoid
        pollMoid = upgradeStatusMoid
    else:
        pollMode = "created-resource"
        pollApiUrl = createdCollection + "/" + createdMoid
        pollMoid = createdMoid
else:
    pollMoid = ""

submissionResultJson = json.dumps({
    "status": submissionStatus,
    "message": submissionMessage,
    "requestAccepted": statusCode == 200,
    "completed": submissionStatus == "completed",
    "targetType": prepared.get("targetType"),
    "targetName": target.get("targetName"),
    "targetMoid": target.get("targetMoid"),
    "imageMoid": imageMoid,
    "imageObjectType": imageObjectType,
    "createdMoid": createdMoid or None,
    "createdObjectType": submitObjectType,
    "upgradeStatusMoid": upgradeStatusMoid or None,
    "pollMode": pollMode or None,
    "waitRequested": bool(prepared.get("waitForCompletion")),
    "acceptedVersusCompletedSemantics": True,
    "retryRequiresInspection": submissionStatus in ("invalid", "failed"),
    "readinessCaveats": target.get("readinessCaveats", []),
    "preflight": preflight
}, separators=(",", ":"))
helperReady = submissionStatus in ("invalid", "failed", "accepted", "completed") and bool(submissionMessage and submissionResultJson) and (submissionStatus == "invalid" or bool(createdMoid and pollMode and pollApiUrl and pollMoid))
